// === Tab: mySketch ===
let randomDuration = Math.floor(Math.random() * (9000 - 3000 + 1) + 3000);
let powerFactor = 0.3;
let speedValue = 15;
let intensityValue = 1;
let followers = [];

let offsetX = 0;
let offsetY = 0;
let easingFactor = 0.15;

let noisePower = Math.floor(Math.random() * (10 - 5 + 1) + 5);

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(20);
  for (let i = 0; i < randomDuration; i++) {
    followers[i] = new Follower();
  }
}

function draw() {
  background(20);

  //fill(220, 50);
  //rect(0, 0, width, 125);

  for (let i = 0; i < followers.length; i++) {
    followers[i].update();
    followers[i].render();
  }

  stroke(255, 50);
  strokeWeight(50);
  let dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - offsetX;
  offsetX += dx * easingFactor;
  let dy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - offsetY;
  offsetY += dy * easingFactor;
  point(offsetX, offsetY);
  noStroke();

  noiseEffect();
}

function noiseEffect() {
  strokeWeight(1);
  for (let i = -width / noisePower; i < width / noisePower - 1; i += 5) {
    for (let j = -height / noisePower; j < height / noisePower - 1; j += 5) {
      fill(random(100, 255), random(20, 40));
      rect(random(0, width), random(0, height), random(1, 2), random(1, 2));
    }
  }
  for (let i = 0; i < 15; i++) {
    fill(random(0, 255), 255);
    rect(random(0, width), random(0, height), 2, 2);
  }
}

class Follower {
  constructor() {
    this.loc = createVector(random(width), random(height));
    this.vel = createVector();
    this.acc = createVector();
  }

  render() {
    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton === LEFT) {
      fill(247, 37, 133, 50);
    } else if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton === RIGHT) {
      fill(76, 201, 241, 50);
    } else {
      fill(255, 255, 255, 50);
    }
    noStroke();
		fill(255);
    ellipse(this.loc.x, this.loc.y, 1.8, 1.8);
  }

  update() {
    this.acc.set(offsetX - this.loc.x, offsetY - this.loc.y);

   /* if (keyIsPressed && key === '+') {
      powerFactor += 0.00001;
    } else if (keyIsPressed && key === '-') {
      powerFactor -= 0.00001;
    } else if (keyIsPressed && (key === 'q' || key === 'Q')) {
      powerFactor = 0.3;
    } else if (keyIsPressed && (key === 's' || key === 'S')) {
      powerFactor = 0.8;
    } else if (keyIsPressed && (key === 'd' || key === 'D')) {
      powerFactor = 1.1;
    } else if (keyIsPressed && (key === 'f' || key === 'F')) {
      powerFactor = 5;
    } else if (keyIsPressed && (key === 'g' || key === 'G')) {
      powerFactor = 10;
    } */

    this.acc.limit(powerFactor);

    this.vel.add(this.acc);

    /*if (keyIsPressed && (key === 'v' || key === 'V')) {
      speedValue = 100;
    } else {
      speedValue = 15;
    }*/

    this.vel.limit(speedValue);

    this.loc.add(this.vel);

    /*if (keyIsPressed && (key === 'a' || key === 'A')) {
      intensityValue = 2;
    } else if (keyIsPressed && (key === 'z' || key === 'Z')) {
      intensityValue = 3;
    } else {
      intensityValue = 1;
    }*/

    this.vel.mult(intensityValue);
  }
}

